let sessionTokenPromise = null;
async function sessionToken() {
  if (!sessionTokenPromise) {
    sessionTokenPromise = fetch('/api/v1/session', {cache:'no-store', headers:{'Accept':'application/json'}})
      .then(async response => {
        if (!response.ok) throw new Error('Unable to initialize browser session. Reload and try again.');
        const session = await response.json();
        if (typeof session.csrf_token !== 'string' || !session.csrf_token) throw new Error('Invalid browser session response');
        return session.csrf_token;
      }).catch(error => { sessionTokenPromise = null; throw error; });
  }
  return sessionTokenPromise;
}

async function api(path, options={}, retried=false) {
  const method = (options.method || 'GET').toUpperCase();
  const readOnly = method === 'GET' || method === 'HEAD' || method === 'OPTIONS';
  const headers = {'Content-Type':'application/json', ...(options.headers || {})};
  if (!readOnly) headers['X-NajdiLab-CSRF'] = await sessionToken();
  const response = await fetch(path, {...options, method, headers});
  let payload;
  try { payload = await response.json(); } catch { payload = {error:'Invalid server response'}; }
  if (!readOnly && !retried && response.status === 403 && payload.code === 'CSRF_TOKEN_INVALID') {
    sessionTokenPromise = null;
    return api(path, options, true);
  }
  if (!response.ok) throw new Error(payload.message || payload.error || `HTTP ${response.status}`);
  return payload;
}

function toast(message, error=false) {
  const el = $('#toast'); el.textContent = message; el.className = `toast show${error?' error':''}`;
  clearTimeout(toast.timer); toast.timer = setTimeout(()=>el.className='toast', 2800);
}

const viewPaths={dashboard:'/',conversations:'/conversations','review-queue':'/review','reviewed':'/gold','add-data':'/data/add','manual-data':'/data/manual',dataset:'/datasets/gold','dataset-health':'/datasets/health',balancer:'/datasets/balancer','dataset-versions':'/datasets/versions',training:'/training/setup','training-jobs':'/training/jobs','eval-sets':'/datasets/eval','human-review':'/evaluation/human-review','phase38-review':'/evaluation/remediation-review','phase39-review':'/evaluation/remediation-review-edits',exports:'/exports',analytics:'/analytics',settings:'/settings'};
const pathViews=Object.fromEntries(Object.entries(viewPaths).map(([view,path])=>[path,view]));
function selectedVersion(){return new URLSearchParams(location.search).get('version')||state.selectedDataset||'';}
function updateLocation(view,version='',replace=false){const path=viewPaths[view]||'/';const query=version?`?version=${encodeURIComponent(version)}`:'';(replace?history.replaceState:history.pushState).call(history,{view,version},'',path+query);}
function switchView(view,options={}) {
  if(!titles[view])view='dashboard';
  if(state.view==='phase38-review'&&view!==state.view&&state.phase38Dirty&&!confirm('You have unsaved remediation changes. Leave this page and discard them?'))return;
  state.view = view;
  $$('.nav-item').forEach(b=>b.classList.toggle('active', b.dataset.view===view));
  $$('.view').forEach(v=>v.classList.toggle('active', v.id===`view-${view}`));
  $('#page-title').textContent = titles[view][0]; $('#page-subtitle').textContent = titles[view][1];
  $('#page-breadcrumb').textContent = view==='dataset-health'?'Datasets > Health':view==='balancer'?'Datasets > Balancer':`NajdiLab / ${titles[view][0]}`;
  if(view==='dataset-health')$('#page-subtitle').textContent='Check the quality, balance, and integrity of a dataset version';
  $('.sidebar').classList.remove('open');
  if(!options.fromHistory)updateLocation(view,options.version||selectedVersion(),options.replace);
  loadView(view).catch(error=>toast(error.message,true));
}

async function loadView(view) {
  if (view==='dashboard') return loadDashboard();
  if (view==='review-queue') return loadQueue();
  if (view==='conversations') return loadConversations();
  if (view==='reviewed') return loadReviewed();
  if (view==='manual-data') return loadManualData();
  if (view==='dataset') return loadDataset();
  if (view==='dataset-health') return loadHealth();
  if (view==='balancer') return loadBalancer();
  if (view==='dataset-versions') return loadDatasetVersions();
  if (view==='training') return loadTrainingSetup();
  if (view==='training-jobs') return loadTrainingJobs();
  if (view==='eval-sets') return loadEvalSets();
  if (view==='human-review') return loadPhase3Review();
  if (view==='phase38-review') return loadPhase38Review();
  if (view==='phase39-review') return loadPhase39Verification();
  if (view==='exports') return loadExports();
  if (view==='analytics') return loadAnalytics();
}

async function loadPhase39Verification(){const host=$('#phase39-status'),list=$('#phase39-records');try{const data=await api('/api/v1/phase39/post-edit-verification');state.phase39=data;state.phase39Index=Math.min(state.phase39Index||0,data.records.length-1);$('#nav-phase39').textContent=`${data.summary.verified}/${data.summary.total}`;renderPhase39Verification();}catch(e){host.textContent=`Unable to load verification status: ${e.message}`;host.className='phase38-status error-state';}}
function renderPhase39Verification(){const data=state.phase39,r=data.records[state.phase39Index],host=$('#phase39-status'),list=$('#phase39-records');host.textContent=`Progress: ${data.summary.verified}/${data.summary.total} · Record ${state.phase39Index+1} of 7`;list.innerHTML=`<article class="phase38-message"><b class="technical-id">${esc(r.record_id)}</b><p dir="auto">${esc(r.record_type)} · ${esc(r.validation_status)} · contamination: ${esc(r.contamination_status||'PASS')} · loss-mask: ${esc(r.loss_mask_status||'PASS')}</p><h4>Original response</h4><p dir="auto">${esc(r.original_assistant_messages)}</p><h4>Reviewer note</h4><p dir="auto">${esc(r.reviewer_note)}</p><h4>Requested correction</h4><p dir="auto">${esc(r.requested_correction)}</p><h4>Applied version</h4><p dir="auto">${esc(r.final_assistant_messages)}</p>${r.record_type==='native_tool_use'?'<p>Tool calls, authoritative results, and record metadata are read-only.</p>':''}</article><label class="wide-label">Verification note<textarea dir="auto" id="phase39-reviewer-note" rows="3">${esc(r.post_edit_note||'')}</textarea></label><div class="phase38-decisions"><button class="button ghost" data-phase39-decision="اعتماد التعديل">Approve edit</button><button class="button ghost" data-phase39-decision="يحتاج تعديل إضافي">Needs further editing</button><button class="button ghost" data-phase39-decision="رفض">Reject</button></div><div class="save-row"><button class="button ghost" data-phase39-nav="prev">Previous</button><button class="button primary" id="phase39-save">Save</button><button class="button ghost" data-phase39-nav="next">Next</button></div>`;$$('[data-phase39-decision]').forEach(b=>b.classList.toggle('selected',b.dataset.phase39Decision===r.decision));bindPhase39Verification();}
function bindPhase39Verification(){const root=$('#view-phase39-review');root.onclick=async e=>{const nav=e.target.closest('[data-phase39-nav]'),decision=e.target.closest('[data-phase39-decision]');if(nav){state.phase39Index=Math.max(0,Math.min(6,state.phase39Index+(nav.dataset.phase39Nav==='next'?1:-1)));renderPhase39Verification();return;}if(decision){state.phase39Decision=decision.dataset.phase39Decision;$$('[data-phase39-decision]').forEach(b=>b.classList.toggle('selected',b===decision));return;}if(!e.target.closest('#phase39-save'))return;if(!state.phase39Decision){toast('Choose a verification decision first',true);return;}const r=state.phase39.records[state.phase39Index];try{const out=await api(`/api/v1/phase39/post-edit-verification/${encodeURIComponent(r.record_id)}`,{method:'POST',body:JSON.stringify({decision:state.phase39Decision,reviewer_note:$('#phase39-reviewer-note').value})});state.phase39=out.verification;state.phase39Decision=null;toast('Verification saved.');renderPhase39Verification();}catch(err){toast(`Unable to save: ${err.message}`,true);}};}

async function ensureDatasetVersions(){
  if(!state.datasetVersions.length){const data=await api('/api/v1/dataset-versions');if(!Array.isArray(data.items))throw new Error('Invalid dataset version response');state.datasetVersions=data.items;}
  const preferred=state.datasetVersions.some(x=>x.version==='gold-v008-split-clean')?'gold-v008-split-clean':state.datasetVersions.some(x=>x.version==='gold-v007-balanced')?'gold-v007-balanced':state.datasetVersions[0]?.version;
  const requested=selectedVersion();state.selectedDataset=state.datasetVersions.some(x=>x.version===requested)?requested:preferred||'';
  ['#health-version','#balance-version','#eval-version'].forEach(selector=>{const select=$(selector);if(!select)return;select.innerHTML=state.datasetVersions.map(x=>`<option value="${esc(x.version)}" ${x.readable===false?'disabled':''}>${esc(x.version)}${x.readable===false?' — Unreadable':''}</option>`).join('');select.value=state.selectedDataset;});
  return preferred;
}

function pct(value){return value==null?'—':`${(Number(value)*100).toFixed(2)}%`;}
function healthCard(title,status,value,description,detail){return `<button class="health-card" data-health-detail="${esc(detail)}"><span class="health-card-status ${esc(String(status).toLowerCase())}">${esc(status)}</span><h3>${esc(title)}</h3><strong>${esc(value)}</strong><p dir="auto">${esc(description)}</p><small>View details</small></button>`;}
function showHealthError(message){$('#health-results').classList.add('hidden');$('#health-state').className='panel health-state error-state';$('#health-state').innerHTML=`<strong>Unable to check dataset health</strong><p dir="auto">${esc(message)}. No changes were made to the dataset and you can safely retry.</p><button id="health-retry" class="button primary">Retry</button>`;$('#health-retry').onclick=()=>loadHealth(true);}
